          toolNotifications: "\u0427\u0438\u0442\u0430\u044E \u0443\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u044F\u2026",
          toolVpnStatus: "\u041F\u0440\u043E\u0432\u0435\u0440\u044F\u044E \u0441\u0442\u0430\u0442\u0443\u0441 VPN\u2026",
          toolVpnConnect: "\u041F\u043E\u0434\u043A\u043B\u044E\u0447\u0430\u044E \u0441\u0430\u043C\u044B\u0439 \u0431\u044B\u0441\u0442\u0440\u044B\u0439 VPN\u2026",
